// requireHostCommandPermission blocks store-level admins from stdio MCP servers, whose command
// runs directly on this host.
func (c *ApiController) requireHostCommandPermission(servers ...*object.Server) bool {
	if c.IsGlobalAdmin() {
		return true
	}
	for _, server := range servers {
		if server.IsStdio() {
			c.ResponseError(c.T("controllers:Only the global admin can configure tools or MCP servers that run commands on the host"))
			return false
		}
	}
	return true
}

// GetServers
// @Title GetServers
// @Tag Server API
// @Description get MCP servers
// @Success 200 {array} object.Server The Response object
// @router /get-servers [get]
func (c *ApiController) GetServers() {
	owner := "admin"
	limit := c.Input().Get("pageSize")
	page := c.Input().Get("p")
	field := c.Input().Get("field")
	value := c.Input().Get("value")
	sortField := c.Input().Get("sortField")
	sortOrder := c.Input().Get("sortOrder")

	if limit == "" || page == "" {
		servers, err := object.GetServers(owner)
		if err != nil {
			c.ResponseError(err.Error())
			return
		}
		c.ResponseOk(object.GetMaskedServers(servers, true))
	} else {
		if !c.RequireAdmin() {
			return
		}
		limit := util.ParseInt(limit)
		count, err := object.GetServerCount(owner, field, value)
		if err != nil {
			c.ResponseError(err.Error())
			return
		}

		paginator := pagination.SetPaginator(c.Ctx, limit, count)
		servers, err := object.GetPaginationServers(owner, paginator.Offset(), limit, field, value, sortField, sortOrder)
		if err != nil {
			c.ResponseError(err.Error())
			return
		}

		c.ResponseOk(object.GetMaskedServers(servers, true), paginator.Nums())
	}
}

